# Merge checkout and search into a new Branch release
node --input-type=module <<'JS'
const { LayerFS, isRefusal } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  try {
    const m = await lf.branch.merge("checkout", "search", "release");
    console.log(m.kind, m.branch);
  } catch (error) {
    if (!isRefusal(error, "Conflict")) throw error;
    console.log(`${error.code}: ${error.message}`);
    for (const c of error.detail?.conflicts ?? []) {
      console.log(`  ${c.path}`);
      for (const h of c.hunks ?? []) {
        for (const t of h.ours ?? []) console.log(`    ours   ${t.trim()}`);
        for (const t of h.theirs ?? []) console.log(`    theirs ${t.trim()}`);
      }
    }
  }
} finally {
  await lf.close();
}
