# Build and test release in a Sandbox and Workspace of my own, then commit, unmount and close
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const { sandbox } = await lf.sandbox.create();
  const ws = await lf.workspace.mount(sandbox, "release");
  try {
    const cmd = "sh build.sh && sh test.sh";
    const run = await lf.workspace.exec(ws, cmd);
    process.stdout.write(`${run.stdout}${run.stderr}`);
    console.log(`exit ${run.exitCode}`);
    const c = await lf.workspace.commit(ws, `lead: ${cmd} (exit ${run.exitCode})`);
    console.log(c.kind, c.merged ? "· my Workspace was stale: merged with the head" : "", c.lww?.length ? `· last writer won ${c.lww.length} path(s)` : "");
  } finally {
    await lf.workspace.unmount(ws);
    await lf.sandbox.close(sandbox);
  }
} finally {
  await lf.close();
}
