# Blame /package.json on main: which call wrote each line
node --input-type=module <<'JS'
const { LayerFS } = await import("@layerfs/agent");
const lf = await LayerFS.open(process.env.LAYERFS_PROJECT);
try {
  const b = await lf.fs.blame("main", "/package.json");
  for (const l of b.lines) console.log(`${String(l.n).padStart(3)} │ ${String(l.message ?? "").slice(0, 56).padEnd(56)} │ ${l.text}`);
  console.log(`from ${b.versions} saved version(s)`);
} finally {
  await lf.close();
}
